	defer cancel()

	runOrNak := func(tasks []NatsMsgTask) {
		if len(tasks) == 0 {
			return
		}
		if drainCtx.Err() != nil {
			for _, t := range tasks {
				t.complete(drainCtx.Err())
			}
			return
		}
		td.executeBatchWithMetrics(drainCtx, tasks)
	}

	for _, b := range pendingBatches {
		runOrNak(b.tasks)
	}
	runOrNak(tailTasks)
}

